const intro = (platform: Platform, topic: Topic, lang: 'en' | 'es') => lang === 'en'
  ? `# ${topic.title.en}\n\n${topic.intent.en}\n\n## Where ${platform.name} and MixingMusic fit\n\n${platform.context.en}\n\nThis guide describes a complementary workflow. MixingMusic.AI is independent from ${platform.name}; the trademark belongs to its owner, and no partnership or endorsement is implied.\n\n## The audio problem to solve\n\n${topic.problem.en}`
  : `# ${topic.title.es}\n\n${topic.intent.es}\n\n## Dónde encajan ${platform.name} y MixingMusic\n\n${platform.context.es}\n\nEsta guía describe un flujo complementario. MixingMusic.AI es independiente de ${platform.name}; la marca pertenece a su titular y no se implica asociación ni respaldo.\n\n## El problema de audio que debemos resolver\n\n${topic.problem.es}`;

const numbered = (items: string[]) => items.map((item, index) => `${index + 1}. ${item}`).join('\n');
const bullets = (items: string[]) => items.map(item => `- ${item}`).join('\n');
const sourceList = (platform: Platform) => platform.sources.map(source => `- [${source.label}](${source.url})`).join('\n');

const content = (platform: Platform, topic: Topic, lang: 'en' | 'es') => `${intro(platform, topic, lang)}

## ${lang === 'en' ? 'Practical workflow' : 'Flujo práctico'}

${numbered(topic.steps[lang])}

## ${lang === 'en' ? 'File handoff to MixingMusic' : 'Entrega de archivos a MixingMusic'}

${platform.handoff[lang]}

## ${lang === 'en' ? 'Quality-control checklist' : 'Lista de control de calidad'}

${bullets(topic.checks[lang])}

## ${lang === 'en' ? 'What MixingMusic cannot repair' : 'Lo que MixingMusic no puede reparar'}

${lang === 'en'
  ? 'Mixing and mastering can improve balance, dynamics, tone and delivery level, but they cannot restore audio information removed by lossy encoding, reverse a committed effect perfectly, guarantee rights, or turn a poor separation into the original multitrack recording. Keep source files and make reversible decisions whenever possible.'
  : 'La mezcla y el mastering pueden mejorar balance, dinámica, tono y nivel de entrega, pero no restauran información eliminada por compresión con pérdida, no revierten perfectamente un efecto impreso, no garantizan derechos ni convierten una separación deficiente en la grabación multipista original. Conserva las fuentes y toma decisiones reversibles cuando sea posible.'}

## ${lang === 'en' ? 'Official references' : 'Referencias oficiales'}

${sourceList(platform)}

${lang === 'en'
  ? 'Product features, plans and export options can change. Confirm the current documentation of the original platform before starting a release-critical project.'
  : 'Las funciones, planes y opciones de exportación pueden cambiar. Confirma la documentación vigente de la plataforma original antes de iniciar un proyecto crítico para publicación.'}`;

const articles: BlogArticle[] = platforms.flatMap((platform, platformIndex) => platform.topics.map((topic, topicIndex) => {
  const excerpt = topic.intent.en;
  const excerptEs = topic.intent.es;
  return {
    id: `workflow-${platform.key}-${topicIndex + 1}`,
    slug: topic.slug,
    title: topic.title.en,
    titleEs: topic.title.es,
    excerpt,
    excerptEs,
    content: content(platform, topic, 'en'),
    contentEs: content(platform, topic, 'es'),
    category: platform.category,
    categoryName: platform.category === 'ai' ? 'AI Music Workflows' : 'Music Production Workflows',
    categoryNameEs: platform.category === 'ai' ? 'Flujos de música con IA' : 'Flujos de producción musical',
    image: '/studio-bg.png',
    author,
    publishDate: `September ${3 - Math.min(2, Math.floor((platformIndex * 10 + topicIndex) / 20))}, 2026`,
    readTime: 7,
    tags: [platform.name, 'MixingMusic.AI', 'Audio Workflow', 'Mixing and Mastering'],
    tagsEs: [platform.name, 'MixingMusic.AI', 'Flujo de audio', 'Mezcla y mastering'],
    seoKeywords: topic.keywords,
    metaDescription: `${topic.intent.en} Practical ${platform.name} and MixingMusic workflow, file preparation and quality checks.`.slice(0, 160),
    metaDescriptionEs: `${topic.intent.es} Flujo práctico con ${platform.name} y MixingMusic, archivos y control de calidad.`.slice(0, 160),
    showComparison: false,
  };
}));

export const platformWorkflowArticles = articles;
